import React from 'react';
import styled from 'styled-components';

// Styled components
const HomeContainer = styled.div`
  padding: 20px;
  text-align: center;
`;

const HeroSection = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  margin-bottom: 20px;

  @media (max-width: 768px) {
    flex-direction: column;
  }
`;

const ProfileImage = styled.img`
  width: 200px;
  height: 200px;
  border-radius: 50%;
  object-fit: cover;
  border: 4px solid #ff6347; // Add a border for a professional look
`;

const TextContent = styled.div`
  max-width: 600px;
  text-align: left;
`;

const Home = () => {
  return (
    <HomeContainer>
      <h1>Welcome to My Portfolio</h1>
      <HeroSection>
        <ProfileImage
          src="C:\Users\attiullah.khanniazi\Downloads\zahid\front.jpg" // Replace with your image URL
          alt="Zahid Hussain"
        />
        <TextContent>
          <p>
            I’m Zahid Hussain, a passionate chef with over 8 years of experience, with a keen eye for taste, texture, and presentation. This portfolio showcases my journey, work experience, and skills that I have honed over the years. Feel free to explore my work, check out my Gallery, and get to know more about what I do. If you have any questions don’t hesitate to reach out! Thank you!!
          </p>
        </TextContent>
      </HeroSection>
    </HomeContainer>
  );
};

export default Home;
